// ==UserScript==
// @name         Alien Lite
// @namespace    urn:witty-alien:chess-theme
// @version      1.0.0
// @description  Alien chessboard and pieces for the Green preset. All images are embedded.
// @author       1qayesy and AI
// @match        https://www.chess.com/*
// @match        https://chess.com/*
// @run-at       document-start
// @grant        none
// @noframes
// ==/UserScript==

(() => {
  'use strict';

  // Embedded at build time so the theme requires no asset hosting.
  const ASSETS = {
  "board": "data:image/webp;base64,",
  "bb": "data:image/webp;base64,",
  "bk": "data:image/webp;base64,",
  "bn": "data:image/webp;base64,",
  "bp": "data:image/webp;base64,",
  "bq": "data:image/webp;base64,",
  "br": "data:image/webp;base64,",
  "wb": "data:image/webp;base64,",
  "wk": "data:image/webp;base64,",
  "wn": "data:image/webp;base64,",
  "wp": "data:image/webp;base64,",
  "wq": "data:image/webp;base64,",
  "wr": "data:image/webp;base64,"
};
  const NAME = 'Alien Lite';
  const STYLE_ID = 'witty-alien-theme-assets';
  const BOARD_MARK = 'data-alien-board';
  const IMAGE_MARK = 'data-alien-image';
  const PREVIEW_MARK = 'data-alien-preview';
  const BOARD_SELECTOR = 'wc-chess-board, chess-board, #board.board, .chessboard';
  const THEME_SELECTOR = `${BOARD_SELECTOR}, style, link[rel="stylesheet"], .theme-selector-assets-board,
    .theme-selector-assets-label, .game-preview-lazy-component`;
  const CODES = ['wp', 'wn', 'wb', 'wr', 'wq', 'wk', 'bp', 'bn', 'bb', 'br', 'bq', 'bk'];

  // Current Green/standard asset IDs, plus the older named asset paths.
  const GREEN_BOARD = /\/image\/9rdwe\/|\/(?:chess-themes\/)?boards\/green\//i;
  const STANDARD_PIECES = /\/image\/ejgfv\/|\/(?:chess-themes\/)?pieces\/neo\//i;
  const originalLabels = new WeakMap();

  function mark(element, attribute, value) {
    if (value === null) {
      if (element.hasAttribute(attribute)) element.removeAttribute(attribute);
    } else if (element.getAttribute(attribute) !== value) {
      element.setAttribute(attribute, value);
    }
  }

  function pieceCode(source) {
    const code = source.match(/\/([wb][pnbrqk])\.png(?:[?#]|$)/i)?.[1]?.toLowerCase();
    return CODES.includes(code) ? code : null;
  }

  function createStyle() {
    const style = document.createElement('style');
    style.id = STYLE_ID;
    const variables = Object.entries(ASSETS)
      .map(([key, source]) => `--alien-image-${key}: url("${source}");`).join('\n');
    const pieceVariables = CODES.map(code =>
      `--theme-piece-set-${code}: var(--alien-image-${code}) !important;`
    ).join('\n');
    const pieceRules = CODES.map(code => `
      [${BOARD_MARK}] .piece.${code},
      [${BOARD_MARK}] .promotion-piece.${code},
      [${BOARD_MARK}] .vfx .element.${code},
      .alien-preview-piece[data-alien-piece="${code}"] {
        background-image: var(--alien-image-${code}) !important;
      }
      img[${IMAGE_MARK}="${code}"] {
        content: var(--alien-image-${code}) !important;
      }
    `).join('\n');
    style.textContent = `
      :root { ${variables} }
      [${BOARD_MARK}] {
        background-image: var(--alien-image-board) !important;
        background-position: center !important;
        background-size: 100% 100% !important;
        background-repeat: no-repeat !important;
        --theme-board-style-coordinate-color-dark: #426e5d;
        --theme-board-style-coordinate-color-light: #deffd0;
        ${pieceVariables}
      }
      [${BOARD_MARK}] .fade-in-overlay {
        background-image: var(--alien-image-board) !important;
        background-size: 100% 100% !important;
      }
      [${BOARD_MARK}] .coordinate-light { fill: #426e5d !important; }
      [${BOARD_MARK}] .coordinate-dark { fill: #deffd0 !important; }
      img[${IMAGE_MARK}="board"] {
        content: var(--alien-image-board) !important;
      }
      [${PREVIEW_MARK}="preset"] {
        background-image: var(--alien-image-board) !important;
        background-size: 400% 400% !important;
        background-position: 16.666667% 0 !important;
        position: relative;
        overflow: hidden;
      }
      .alien-preview-piece {
        position: absolute;
        width: 50%;
        height: 50%;
        background-size: 100% 100%;
        background-position: center;
        background-repeat: no-repeat;
        pointer-events: none;
      }
      ${pieceRules}
    `;
    document.documentElement.appendChild(style);
  }

  function isGreenStandardBoard(board, rootTheme) {
    // wc-chess-board creates a per-board style node, including its own preview
    // selection. Reading that source avoids detecting our CSS as a new theme.
    const suffix = board.id.replace(/^board-/, '');
    const style = suffix && document.getElementById(`board-styles-${suffix}`);
    if (style) {
      const text = style.textContent || '';
      const blocks = text.matchAll(/([^{}]+)\{([^{}]*)\}/g);
      for (const block of blocks) {
        if (block[1].split(',').some(selector => selector.trim() === `#${board.id}`)) {
          return GREEN_BOARD.test(block[2]) && STANDARD_PIECES.test(text);
        }
      }
    }

    // The /play landing board renders pieces as CSS background layers and
    // inherits the theme's custom properties rather than using .piece nodes.
    const inline = board.style.backgroundImage || board.style.background || '';
    if ((!inline || inline.includes('--theme-board-style-image')) && rootTheme.board && rootTheme.pawn) {
      return GREEN_BOARD.test(rootTheme.board) && STANDARD_PIECES.test(rootTheme.pawn);
    }

    // Compatibility fallback: synchronously remove only our marker to read
    // native computed styles. No DOM positions, transforms or game state change.
    const hadMarker = board.hasAttribute(BOARD_MARK);
    if (hadMarker) board.removeAttribute(BOARD_MARK);
    try {
      const computed = getComputedStyle(board);
      const piece = board.querySelector('.piece, .promotion-piece');
      const nativePiece = piece
        ? getComputedStyle(piece).backgroundImage
        : computed.getPropertyValue('--theme-piece-set-wp');
      return GREEN_BOARD.test(computed.backgroundImage) && STANDARD_PIECES.test(nativePiece);
    } finally {
      if (hadMarker) board.setAttribute(BOARD_MARK, '');
    }
  }

  function syncBoards() {
    const computed = getComputedStyle(document.documentElement);
    const rootTheme = {
      board: computed.getPropertyValue('--theme-board-style-image').trim(),
      pawn: computed.getPropertyValue('--theme-piece-set-wp').trim(),
    };
    const boards = [...document.querySelectorAll(BOARD_SELECTOR)];
    for (const board of boards) {
      mark(board, BOARD_MARK, isGreenStandardBoard(board, rootTheme) ? '' : null);
    }
    return boards;
  }

  function syncPresetCards() {
    for (const preview of document.querySelectorAll('.theme-selector-assets-board')) {
      // Keep the native inline URLs and Vue click handlers intact. The Green
      // preset is the combination of this board AND the standard piece set.
      const source = preview.style.backgroundImage;
      const isPreset = GREEN_BOARD.test(source) && STANDARD_PIECES.test(source);
      const label = preview.parentElement?.querySelector('.theme-selector-assets-label');
      mark(preview, PREVIEW_MARK, isPreset ? 'preset' : null);
      if (isPreset) {
        if (label) {
          if (!originalLabels.has(preview)) {
            originalLabels.set(preview, { text: label.textContent, title: label.getAttribute('title') });
          }
          if (label.textContent !== NAME) label.textContent = NAME;
          if (label.getAttribute('title') !== NAME) label.setAttribute('title', NAME);
        }
        if (!preview.querySelector('.alien-preview-piece')) {
          ['bn', 'wn', 'bp', 'wp'].forEach((code, index) => {
            const piece = document.createElement('span');
            piece.className = 'alien-preview-piece';
            piece.dataset.alienPiece = code;
            piece.setAttribute('aria-hidden', 'true');
            piece.style.left = `${(index % 2) * 50}%`;
            piece.style.top = `${Math.floor(index / 2) * 50}%`;
            preview.appendChild(piece);
          });
        }
      } else {
        preview.querySelectorAll('.alien-preview-piece').forEach(piece => piece.remove());
        // Vue may recycle a preview card for a different item in the list.
        const previous = originalLabels.get(preview);
        if (label && previous) {
          if (label.textContent === NAME) label.textContent = previous.text;
          if (label.getAttribute('title') === NAME) {
            if (previous.title === null) label.removeAttribute('title');
            else label.setAttribute('title', previous.title);
          }
        }
        originalLabels.delete(preview);
      }
    }
  }

  function syncImagePreviews() {
    // Lazy game/result previews use <img> elements. CSS content replaces their
    // appearance without rewriting src or interfering with native image loading.
    for (const preview of document.querySelectorAll('.game-preview-lazy-component')) {
      const board = preview.querySelector('img.game-preview-lazy-board');
      const pieces = [...preview.querySelectorAll('img.game-preview-lazy-piece')];
      const enabled = !!board && GREEN_BOARD.test(board.getAttribute('src') || '') &&
        pieces.length > 0 && pieces.every(piece => STANDARD_PIECES.test(piece.getAttribute('src') || ''));
      if (board) mark(board, IMAGE_MARK, enabled ? 'board' : null);
      for (const piece of pieces) {
        mark(piece, IMAGE_MARK, enabled ? pieceCode(piece.getAttribute('src') || '') : null);
      }
    }
  }

  function start() {
    if (document.getElementById(STYLE_ID)) return;
    createStyle();

    let pending = false;
    function sync() {
      pending = false;
      syncBoards();
      syncPresetCards();
      syncImagePreviews();
    }

    function schedule() {
      if (pending) return;
      pending = true;
      requestAnimationFrame(sync);
    }

    const observer = new MutationObserver(records => {
      for (const record of records) {
        const target = record.target.nodeType === Node.ELEMENT_NODE
          ? record.target : record.target.parentElement;
        if (!target || target.closest(`#${STYLE_ID}, .alien-preview-piece`)) continue;

        const owner = target.closest(THEME_SELECTOR);
        // Moving pieces are already themed via CSS. Only watch their board
        // container and changes to the site's stylesheet or theme previews.
        if (owner?.matches(BOARD_SELECTOR) && owner !== target) continue;
        const themeChanged = owner || (record.type === 'attributes' && target.matches('html, body'));
        const themeMounted = !themeChanged && record.type === 'childList' &&
          [...record.addedNodes].some(node => node.nodeType === Node.ELEMENT_NODE &&
            (node.matches(THEME_SELECTOR) || node.querySelector(THEME_SELECTOR)));
        if (themeChanged || themeMounted) {
          schedule();
          break;
        }
      }
    });
    observer.observe(document.documentElement, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: ['class', 'style', 'src', 'srcset', 'href', 'title', 'id'],
    });

    document.addEventListener('load', event => {
      if (event.target instanceof HTMLLinkElement) schedule();
    }, true);
    document.addEventListener('DOMContentLoaded', schedule, { once: true });
    window.addEventListener('pageshow', schedule);
    sync();
  }

  if (document.documentElement) start();
  else {
    const ready = new MutationObserver(() => {
      if (document.documentElement) {
        ready.disconnect();
        start();
      }
    });
    ready.observe(document, { childList: true });
  }
})();
